template <typename T>
class CustomPtr {
    T* resource;
public:
    T* get() const { return resource; }
    CustomPtr(T* p) : resource(p) {}
};

// Overloading Smart Ptr vs. nullptr
template <typename T>
bool operator!=(const CustomPtr<T>& p,
                std::nullptr_t) noexcept
{
    return p.get() != nullptr;
}

// Overloading nullptr vs. Smart Ptr (Symmetry)
template <typename T>
bool operator!=(std::nullptr_t,
                const CustomPtr<T>& p) noexcept
{
    return p.get() != nullptr;
}
